from .service import stream_rows


def _close_preserving_error(stream):
    # Used only while another error is active: a cleanup failure must not
    # replace the original error.
    try:
        stream.close()
    except BaseException:
        pass


def take(resource, transform, limit):
    if limit <= 0:
        # Nothing requested: return without starting the stream.
        return []
    stream = stream_rows(resource, transform)
    result = []
    try:
        for row in stream:
            result.append(row)
            if len(result) >= limit:
                break
    except BaseException:
        _close_preserving_error(stream)
        raise
    # Success path (limit reached or stream exhausted): no error is active, so
    # a cleanup failure propagates. Closing a finished stream is a no-op.
    stream.close()
    return result

