def stream_rows(resource, transform):
    # Generator function: constructing it, or closing it before the first
    # next(), never runs this body, so neither read_next() nor close() is called.
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        # Explicit close() (or garbage collection) is not an error: a cleanup
        # failure here propagates out of generator.close().
        resource.close()
        raise
    except BaseException:
        # An iteration or transform error is active: a cleanup failure must not
        # replace it, so the original error is re-raised.
        try:
            resource.close()
        except BaseException:
            pass
        raise
    else:
        # Exhaustion: no error is active, so a cleanup failure propagates.
        resource.close()
